 public static object Run(){var scene=EditorSceneManager.NewPreviewScene();RenderTexture target=null;Texture2D image=null;var old=RenderTexture.active;try{var c=new GameObject("Wreck review camera").AddComponent<Camera>();SceneManager.MoveGameObjectToScene(c.gameObject,scene);c.enabled=false;c.scene=scene;c.overrideSceneCullingMask=EditorSceneManager.GetSceneCullingMask(scene);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.15f,.18f,.22f);c.fieldOfView=42;c.nearClipPlane=.1f;c.farClipPlane=200;target=new RenderTexture(1400,750,24);target.Create();c.targetTexture=target;var light=new GameObject("Review sunlight").AddComponent<Light>();SceneManager.MoveGameObjectToScene(light.gameObject,scene);light.type=LightType.Directional;light.intensity=2;light.shadows=LightShadows.Soft;light.transform.rotation=Quaternion.Euler(45,-40,0);
  string dir="Assets/Blueprinter/Mods/Gunmageddon/";string[] paths={"C127/C127T_Emplacement.prefab","Wreckage/C127T_Emplacement_Wreck.prefab","Wreckage/F120_AAA_Trailer_Wreck.prefab","Wreckage/Searchlight_Trailer_Wreck.prefab"};int i=0;foreach(string path in paths){var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(dir+path));SceneManager.MoveGameObjectToScene(root,scene);root.transform.position=new Vector3((i++-1.5f)*10,0,0);foreach(var group in root.GetComponentsInChildren<LODGroup>(true))group.ForceLOD(0);}var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);SceneManager.MoveGameObjectToScene(floor,scene);floor.transform.localScale=new Vector3(10,1,8);floor.transform.position=new Vector3(0,-.02f,0);var floorMat=new Material(Shader.Find("Universal Render Pipeline/Lit"));floorMat.color=new Color(.3f,.31f,.3f);floor.GetComponent<Renderer>().sharedMaterial=floorMat;c.transform.position=new Vector3(27,17,33);c.transform.LookAt(new Vector3(0,1.2f,0));c.Render();RenderTexture.active=target;image=new Texture2D(1400,750,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1400,750),0,0);image.Apply();string pathOut=System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "UnitySetupBackup/Wreckage/Preview.png");Directory.CreateDirectory(Path.GetDirectoryName(pathOut));File.WriteAllBytes(pathOut,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(floorMat);return pathOut;}finally{RenderTexture.active=old;if(image)UnityEngine.Object.DestroyImmediate(image);if(target){target.Release();UnityEngine.Object.DestroyImmediate(target);}EditorSceneManager.ClosePreviewScene(scene);}}
